#[path = "solution.rs"]
mod solution;

use solution::{bell_code, AppendOnDivisor};

#[test]
fn append_on_divisor_appends_once_only_when_divisible() {
    let mut output = String::from("start:");
    12_i64.append_on_divisor(4, "Ding", &mut output);
    assert_eq!(output, "start:Ding");

    10_i64.append_on_divisor(4, "no", &mut output);
    assert_eq!(output, "start:Ding");

    (-18_i64).append_on_divisor(6, "!", &mut output);
    assert_eq!(output, "start:Ding!");
}

#[test]
fn zero_divisor_does_nothing_without_panicking() {
    let mut output = String::from("unchanged");
    i64::MIN.append_on_divisor(0, "bad", &mut output);
    assert_eq!(output, "unchanged");
}

#[test]
fn bell_code_uses_the_required_word_order() {
    assert_eq!(bell_code(4), "Ding");
    assert_eq!(bell_code(6), "Dang");
    assert_eq!(bell_code(9), "Dong");
    assert_eq!(bell_code(12), "DingDang");
    assert_eq!(bell_code(18), "DangDong");
    assert_eq!(bell_code(36), "DingDangDong");
}

#[test]
fn zero_is_divisible_by_all_nonzero_divisors() {
    assert_eq!(bell_code(0), "DingDangDong");
}

#[test]
fn negative_values_follow_normal_divisibility_and_signed_fallback() {
    assert_eq!(bell_code(-12), "DingDang");
    assert_eq!(bell_code(-9), "Dong");
    assert_eq!(bell_code(-5), "-5");
}

#[test]
fn integer_extremes_are_handled_without_overflow() {
    assert_eq!(bell_code(i64::MIN), "Ding");
    assert_eq!(bell_code(i64::MAX), i64::MAX.to_string());
}

